private static string calculImpot(StreamWriter writer, int numClient, string[] champs) {
             // request calculation married(Y/N) nbEnfants salaireAnnuel
             // 4 fields are required
            if (champs.Length != 4) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // fields [1]
            string marié = champs[1];
            if (marié != "o" &amp;&amp; marié != "n") {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // fields [2]
            int nbEnfants;
            if (!int.TryParse(champs[2], out nbEnfants)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // fields [3]
            int salaireAnnuel;
            if (!int.TryParse(champs[3], out salaireAnnuel)) {
                return "Commande calcul incorrecte. Utilisez la commande aide.";
            }
             // that's it - tax calculation
            int impot = 0;
            try {
                impot = metier.CalculerImpot(marié == "o", nbEnfants, salaireAnnuel);
                return impot.ToString();
            } catch (Exception ex) {
                return ex.Message;
            }
        }
</code></pre> <ul> <li>السطر 1: تستقبل الطريقة مصفوفة حقول الأوامر كمعلمة ثالثة tax. إذا تمت صياغتها بشكل صحيح، فإنها تكون على الشكل married tax nbEnfants salaireAnnuel. نتيجة الطريقة هي الاستجابة التي سيتم إرسالها إلى العميل.   </li> <li>السطر 4: تحقق من أن الأمر يحتوي على 4 حقول   </li> <li>السطر 8: تحقق من صحة married </li> <li>السطر 14: تحقق من صحة nbEnfants </li> <li>السطر 19: تحقق من صحة salaireAnnuel </li> <li>السطر 25: يتم حساب الضريبة باستخدام CalculerImpot من طبقة [metier]. تذكر أن هذه الطبقة مغلفة في DLL. </li> <li>السطر 26: إذا عادت طبقة [metier] بنتيجة، يتم إرجاعها إلى العميل.   </li> <li>السطر 28: إذا أطلقت طبقة [metier] استثناءً، يتم إرجاع رسالة الاستثناء إلى العميل.   </li> </ul> <p></p>

هناك عدة أنواع من أشرطة التمرير:محرك الأفقية (HscrollBar)،شريط التمرير الرأسي (VscrollBar)،المزيد (NumericUpDown). <p>دعونا نقوم بتشغيل التطبيق التالي:</p> رقمالنوعالاسمالدور1hScrollBarhScrollBar1محرك أفقي2hScrollBarhScrollBar2متغير أفقي يتبع تغيرات المتغير 13التسميةlabelValeurHS1يعرض قيمة المحرك الأفقي4NumericUpDownرقمي لأعلى ولأسفل 2لتعيين قيمة وحدة التحكم 2 <p>يتيح شريط التمرير العكسي للمستخدم اختيار قيمة من نطاق من القيم الصحيحة التي يمثلها "نطاق" محرك الأقراص الذي يتحرك عليه المؤشر. وتتوفر قيمة محرك الأقراص في خاصية Value.</p> <ul> <li>بالنسبة للمحرك الأفقي، يمثل الطرف الأيسر القيمة الدنيا للنطاق، والطرف الأيمن القيمة القصوى، والمؤشر القيمة المحددة حاليًا. بالنسبة للمحرك الرأسي، يمثل الطرف العلوي القيمة الدنيا، والطرف السفلي القيمة القصوى. يتم تمثيل هذه القيم بواسطة الخصائص Minimum و Maximum، والقيم الافتراضية هي 0 و 100.   </li> <li>يؤدي النقر على طرفي المحرك إلى تغيير القيمة بمقدار وحدة واحدة (موجبة أو سالبة) اعتمادًا على الطرف الذي تم النقر عليه SmallChange والذي يبلغ افتراضيًا 1.   </li> <li>يؤدي النقر على أي من جانبي المؤشر إلى تغيير القيمة بمقدار وحدة واحدة (موجبة أو سالبة)، اعتمادًا على الطرف الذي تم النقر عليه LargeChange والذي تبلغ قيمته الافتراضية 10.   </li> <li>عند النقر على الطرف العلوي لمزج الإضاءة العمودي، تنخفض قيمته. قد يكون هذا مفاجئًا للمستخدم العادي، الذي يتوقع عادةً أن "ترتفع" القيمة. يتم حل هذه المشكلة عن طريق إعطاء قيمة سالبة للخصائص SmallChange و LargeChange </li> <li>هذه الخصائص الخمس (Value، Minimum، Maximum، SmallChange، LargeChange) متاحة للقراءة والكتابة.   </li> <li>الحدث الرئيسي للمحرك هو الذي يشير إلى تغيير في القيمة: Scroll.   </li> </ul> <p>يشبه المكون NumericUpDown مكون محرك الأقراص: فهو يحتوي أيضًا على الخصائص التالية: Minimum و Maximum و Value، والقيم الافتراضية هي 0 و 100 و 0. ولكن هنا، يتم عرض القيمة (Value) في مربع إدخال يمثل جزءًا لا يتجزأ من عنصر التحكم. يمكن للمستخدم نفسه تعديل هذه القيمة ما لم يتم تعيين خاصية ReadOnly إلى true. يتم تعيين قيمة الزيادة بواسطة Incrementally، والقيمة الافتراضية هي 1. الحدث الرئيسي لمكون NumericUpDown هو الذي يشير إلى تغيير في القيمة: الحدث ValueChanged</p> <p>رمز التطبيق هو كما يلي:</p> <pre><code>
